public void run()
{
    DemoCustomer customer = DemoCustomer::find('C0001');
    real limit;
    str customerName;
    var helper = new ContosoHelper();

    limit = customer.creditMax();
    customerName = DemoCustomer::find('C0002').name();
    limit += helper.calc_Total();
    limit += new ContosoHelper().customer().creditMax();

    if (limit > 1000)
    {
        info(strFmt("@DemoLabels:CreditLimit", limit));
    }

    ttsbegin;
    customer.selectForUpdate(true);
    customer.update();
    ttscommit;
}
